// Permisos que SSH comprueba en el servidor para el usuario ec2-user. Corrige el defecto principal.
export const permisosServidor = {
  usuario: "ec2-user",
  directorioPersonal: { ruta: "/home/ec2-user", modo: "777" },
  carpetaSsh: { ruta: "/home/ec2-user/.ssh", modo: "700" },
  authorizedKeys: { ruta: "/home/ec2-user/.ssh/authorized_keys", modo: "600" },
};

solution.code:
export const permisosServidor = {
  usuario: "ec2-user",
  directorioPersonal: { ruta: "/home/ec2-user", modo: "700" },
  carpetaSsh: { ruta: "/home/ec2-user/.ssh", modo: "700" },
  authorizedKeys: { ruta: "/home/ec2-user/.ssh/authorized_keys", modo: "600" },
};

spec.code:
for (const ruta of [permisosServidor.directorioPersonal, permisosServidor.carpetaSsh, permisosServidor.authorizedKeys]) {
  assert.match(ruta.modo, /^[0-7]00$/, ruta.ruta + " debe quedar limitada al dueño");
}

for (const ruta of [permisosServidor.directorioPersonal, permisosServidor.carpetaSsh, permisosServidor.authorizedKeys]) {
  assert.strictEqual(typeof ruta.modo, "string");
  assert.match(ruta.modo, /^[0-7]{3}$/);
}

