// Plan de actuación ante «Host key verification failed» tras cambiar la IP pública. Corrige su defecto principal.
export const plan = {
  error: "Host key verification failed",
  causa: "La huella guardada en known_hosts no coincide con la que presenta la instancia tras cambiar su IP pública.",
  pasos: ["actualizar-known-hosts", "confirmar-cambio", "verificar-huella", "conectar"],
};

solution.code:
export const plan = {
  error: "Host key verification failed",
  causa: "La huella guardada en known_hosts no coincide con la que presenta la instancia tras cambiar su IP pública.",
  pasos: ["confirmar-cambio", "verificar-huella", "actualizar-known-hosts", "conectar"],
};

spec.code:
const verificar = plan.pasos.indexOf("verificar-huella");
assert.ok(verificar >= 0, "falta verificar la huella");
assert.ok(verificar < plan.pasos.indexOf("conectar"), "la huella debe verificarse antes de conectar");
